        public void Print(
            ITerminalGetter item,
            StructuredStringBuilder sb,
            string? name = null,
            Terminal.Mask<bool>? printMask = null)
        {
            if (name == null)
            {
                sb.AppendLine($"Terminal =>");
            }
            else
            {
                sb.AppendLine($"{name} (Terminal) =>");
            }
            using (sb.Brace())
            {
                ToStringFields(
                    item: item,
                    sb: sb,
                    printMask: printMask);
            }
        }
        
